use std :: str :: FromStr ; use chrono :: { DateTime , Utc } ; use derive_more :: derive :: Display ; use derive_setters :: Setters ; use serde :: { Deserialize , Serialize } ; use uuid :: Uuid ; use crate :: { Context , Error , Metrics , Result , TokenCount } ; use pretty_assertions :: assert_eq ; use super :: * ; use crate :: { Context , ContextMessage , ToolOutput , ToolResult , ToolValue } ; use crate :: { MessageEntry , Usage } ; use crate :: { MessageEntry , Usage } ; impl Conversation { pub fn new (id : ConversationId) -> Self { let created_at = Utc :: now () ; let metrics = Metrics :: default () . started_at (created_at) ; Self { id , metrics , metadata : MetaData :: new (created_at) , title : None , context : None , } } # [doc = " Creates a new conversation with a new conversation ID."] # [doc = ""] # [doc = " This is a convenience constructor that automatically generates a unique"] # [doc = " conversation ID, making it easy to create new conversations without"] # [doc = " having to manually create the ID."] pub fn generate () -> Self { Self :: new (ConversationId :: generate ()) } # [doc = " Generates an HTML representation of the conversation"] # [doc = ""] # [doc = " This method uses Handlebars to render the conversation as HTML"] # [doc = " from the template file, including all agents, events, and variables."] # [doc = ""] # [doc = " # Errors"] # [doc = " - If the template file cannot be found or read"] # [doc = " - If the Handlebars template registration fails"] # [doc = " - If the template rendering fails"] pub fn to_html (& self) -> String { crate :: conversation_html :: render_conversation_html (self) } # [doc = " Generates an HTML representation with related agent conversations"] # [doc = ""] # [doc = " Creates a single HTML document containing the main conversation"] # [doc = " and all related agent conversations with anchor links for navigation."] pub fn to_html_with_related (& self , related : & [Conversation]) -> String { crate :: conversation_html :: render_conversation_html_with_related (self , related) } # [doc = " Returns a vector of user messages, selecting the first message from"] # [doc = " each consecutive sequence of user messages."] pub fn first_user_messages (& self) -> Vec < & crate :: ContextMessage > { self . context . as_ref () . map (| ctx | ctx . first_user_messages ()) . unwrap_or_default () } # [doc = " Returns the total token usage across all messages in the conversation."] # [doc = ""] # [doc = " This is a convenience method that aggregates usage from the context,"] # [doc = " if available."] pub fn accumulated_usage (& self) -> Option < crate :: Usage > { self . context . as_ref () . and_then (| ctx | ctx . accumulate_usage ()) } pub fn usage (& self) -> Option < crate :: Usage > { self . context . iter () . flat_map (| ctx | ctx . messages . iter ()) . flat_map (| msg | msg . usage . into_iter ()) . last () } pub fn token_count (& self) -> Option < TokenCount > { self . context . as_ref () . map (| ctx | ctx . token_count ()) } pub fn accumulated_cost (& self) -> Option < f64 > { self . accumulated_usage () . and_then (| usage | usage . cost) } # [doc = " Calculates the total cost including related conversations."] # [doc = ""] # [doc = " This method sums the costs of the current conversation and all related"] # [doc = " conversations provided. It's useful for computing the total cost of a"] # [doc = " conversation tree when agent tools spawn child conversations."] # [doc = ""] # [doc = " # Arguments"] # [doc = ""] # [doc = " * `conversations` - A slice of conversations to include in cost"] # [doc = "   calculation"] pub fn total_cost (conversations : & [Conversation]) -> Option < f64 > { let costs : Vec < f64 > = conversations . iter () . filter_map (| conv | conv . accumulated_cost ()) . collect () ; if costs . is_empty () { return None ; } Some (costs . iter () . sum ()) } # [doc = " Returns the number of messages in the conversation context."] # [doc = ""] # [doc = " Returns `0` if the context has not been initialized yet."] pub fn len (& self) -> usize { self . context . as_ref () . map (| ctx | ctx . messages . len ()) . unwrap_or (0) } # [doc = " Returns `true` if the conversation context has no messages."] pub fn is_empty (& self) -> bool { self . len () == 0 } # [doc = " Extracts all related conversation IDs from agent tool calls."] # [doc = ""] # [doc = " This method scans through all tool results in the conversation's context"] # [doc = " and collects conversation IDs from AI tool values, which are created"] # [doc = " when agent tools are called and trigger new conversations."] pub fn related_conversation_ids (& self) -> Vec < ConversationId > { self . context . as_ref () . map (| ctx | { ctx . messages . iter () . filter_map (| msg | msg . as_tool_result ()) . flat_map (| result | & result . output . values) . filter_map (| value | { if let crate :: ToolValue :: AI { conversation_id , .. } = value { Some (conversation_id) } else { None } }) . copied () . collect () }) . unwrap_or_default () } }